import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { atomicMemoryPcaStore } from './server/require-pca';
import { createAuthorizer } from './server/authorize';
import type { Capability } from './capability';
import type { PCActn } from './pcactn';

// Rules 20 (units) and 21 (tighten-only) end to end through authorize(), shared with the Go, Rust and Python verifiers:
// conformance/model-rules-vectors.json (generated by scripts/gen-conformance-model-rules.mjs from this reference). Every
// committed expectation is recomputed here, so a reference change that is not regenerated fails.
interface Case {
  name: string;
  grant: Capability;
  pcactn: PCActn;
  operation: { verb: string; resource: string; params: Record<string, unknown> };
  intent_v2?: unknown;
  context?: { env?: unknown };
  expect: { allow: boolean; decision: string; status: number; failed: string[]; reasons: string[]; degraded?: Record<string, string>; units?: string; tighten?: string };
}
const doc = JSON.parse(readFileSync(new URL('../conformance/model-rules-vectors.json', import.meta.url), 'utf8')) as { now: number; audience: string; cases: Case[] };
const MODEL = /^(units|tighten|schema|intent_session): /;

describe('model-rules-vectors.json', () => {
  it.each(doc.cases)('$name', async (c) => {
    const run = createAuthorizer({
      audience: doc.audience,
      resolveGrant: async (ref: string) => (ref === c.grant.id ? c.grant : null),
      budgetStore: atomicMemoryPcaStore(),
      hooks: { revocation: () => ({ enforced: true, ok: true }) },
      plan: 'single-step',
      now: () => doc.now,
      ...(c.intent_v2 !== undefined ? { intentV2: c.intent_v2 as never } : {}),
      context: async () => ({ ...(c.context?.env !== undefined ? { env: c.context.env as never } : {}) }),
    } as never);
    const r = await run({ pcactn: c.pcactn, operation: c.operation });
    const checks = r.verdict?.checks ?? {};
    const degraded = Object.fromEntries(Object.entries(r.assurance ?? {}).filter(([, e]) => (e as { degraded?: boolean })?.degraded === true).map(([n, e]) => [n, (e as { reason: string }).reason]));
    expect({
      allow: r.allow,
      decision: r.decision,
      status: r.status,
      failed: Object.entries(checks).filter(([, s]) => s === 'fail').map(([n]) => n).sort(),
      reasons: (r.verdict?.reasons ?? []).filter((x) => MODEL.test(x)),
      ...(Object.keys(degraded).length ? { degraded } : {}),
      ...(checks.units !== undefined ? { units: checks.units } : {}),
      ...(checks.tighten !== undefined ? { tighten: checks.tighten } : {}),
    }).toEqual(c.expect);
  });

  it('exercises allow, escalate and deny', () => {
    expect(new Set(doc.cases.map((c) => c.expect.decision))).toEqual(new Set(['allow', 'escalate', 'deny']));
  });
});
